import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const p = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "src", "telegramGroupVault.mjs");
let c = fs.readFileSync(p, "utf8");
if (c.includes("everything that.?s best") || c.includes("everything\\s+that")) {
  console.log("looksLikeInstallGo already expanded");
  process.exit(0);
}
const neu = `export function looksLikeInstallGo(text) {
  const t = String(text || "");
  return (
    /\\b(install\\s+(go|ok|yes|approved)|approve\\s+install|greenlight\\s+install|you'?re?\\s+good\\s+to\\s+install|go\\s+ahead\\s+and\\s+install)\\b/i.test(
      t,
    ) ||
    /\\beverything\\s+that'?s\\s+best\\b/i.test(t) ||
    /\\byou\\s+know\\s+how\\s+i\\s+like\\s+things\\b/i.test(t) ||
    /\\b(full\\s+install|install\\s+full|best\\s+scopes?|full\\s+scopes?)\\b/i.test(t)
  );
}`;
if (!/export function looksLikeInstallGo\(text\) \{[\s\S]*?\n\}/.test(c)) {
  throw new Error("looksLikeInstallGo block not found");
}
c = c.replace(/export function looksLikeInstallGo\(text\) \{[\s\S]*?\n\}/, neu);
fs.writeFileSync(p, c);
console.log("looksLikeInstallGo expanded");

